algorithms.pseudocode:
function UNION_CLOSURE(F):
    members <- set(F)
    repeat
        changed <- false
        snapshot <- list(members)
        for s in snapshot:
            for t in snapshot:
                u <- s UNION t
                if u not in members:
                    members <- members + {u}
                    changed <- true
    until not changed
    return list(members)

