\documentclass[11pt]{amsart}

\usepackage{amsmath,amssymb,amsthm}
\usepackage[margin=1in]{geometry}
\usepackage{hyperref}

\theoremstyle{plain}
\newtheorem{theorem}{Theorem}
\newtheorem{lemma}{Lemma}
\theoremstyle{definition}
\newtheorem{definition}{Definition}

\DeclareMathOperator{\mc}{mc}
\DeclareMathOperator{\jc}{jc}
\DeclareMathOperator{\uc}{uc}
\newcommand{\card}[1]{\lvert #1 \rvert}
\newcommand{\closure}[1]{\overline{#1}}

\title{Union-Closed Families as Positive-Correlation Systems}
\author{Aristotle}
\date{June 21, 2026}

\begin{document}

\begin{abstract}
We develop a self-contained theory linking \emph{union-closed set families} to
the positive-correlation phenomena of discrete statistical mechanics. Working
over a finite ground set $\alpha$, we treat a finite family $F$ of subsets as a
uniform probability space of configurations and study three observables: the
per-site \emph{member count} $\mc(a)$, the \emph{joint count} $\jc(a,b)$, and the
\emph{union count} $\uc(a,b)$. We establish: (1) a double-counting identity
equating total occupancy with total configuration size; (2) a
majority-from-average principle producing a frequently occurring element under
an averaged size hypothesis---a verified instance of the Frankl direction; (3) a
bridge theorem showing every upper-set family is union-closed; (4) the two-point
inclusion--exclusion identity; (5) the construction of the union closure as a
closure operator together with monotonicity of total occupancy under closure;
and (6) the FKG base case: nonnegative correlation of coordinate indicators on
the full powerset. Each result is interpreted in the language of lattice
gases. All statements correspond to fully formal, machine-checked theorems.
\end{abstract}

\maketitle

\section{Introduction}

Union-closed families sit at a crossroads. Combinatorially, they are families
$F$ of finite sets closed under pairwise union; the celebrated \emph{Frankl
conjecture} (1979) asserts that any such family containing a nonempty set has an
element belonging to at least half its members. Order-theoretically, they
generalize \emph{filters} (upper sets) in a Boolean lattice. Probabilistically, a
finite family is a uniform measure on configurations of a discrete particle
system, and union-closure is a monotone constraint encouraging aggregation.

Our aim is to make this last reading rigorous and to isolate the elementary
facts on which any correlation theory of such systems must rest. The value of
the results is the dictionary they assemble between combinatorics and
statistical mechanics:
\[
\begin{array}{ll}
\mc(a)/\card{F} & \text{marginal occupancy of site } a \\
\jc(a,b)/\card{F} & \text{two-point correlation function} \\
\sum_{s\in F}\card{s} & \text{total particle number over all configurations} \\
\closure{F} & \text{coarse-graining / closure dynamics} \\
\text{frequent element} & \text{nonzero order parameter} \\
\text{powerset correlation} & \text{finite FKG base case}
\end{array}
\]

Throughout, $\alpha$ is a type with decidable equality; where stated it is also
finite, with $\card{\alpha}$ its cardinality. Subsets of $\alpha$ are finite
sets, and a \emph{family} is a finite set $F$ of such subsets. We write
$\card{s}$ for the cardinality of $s$, $\card{F}$ for the number of members of
$F$, and $2^\alpha$ for the family of all subsets of $\alpha$, with
$\card{2^\alpha} = 2^{\card{\alpha}}$.

\section{Definitions}

\begin{definition}[Union-closed family]
A family $F$ is \emph{union-closed} if
$\forall\, s,t \in F,\ s \cup t \in F$. This models a configuration space closed
under binary joins---a monotone lattice gas.
\end{definition}

\begin{definition}[Upper-set family]
A family $F$ is an \emph{upper-set family} (upset) if
$\forall\, s,t,\ s \in F \wedge s \subseteq t \Rightarrow t \in F$. For finite
$\alpha$ this is an order filter in the Boolean lattice $2^\alpha$.
\end{definition}

\begin{definition}[Member count]
For $a \in \alpha$, $\mc(a) := \#\{\, s \in F : a \in s \,\}$, equal to $\card{F}$
times the marginal occupancy probability of site $a$ under the uniform measure
on $F$.
\end{definition}

\begin{definition}[Joint count]
For $a,b \in \alpha$, $\jc(a,b) := \#\{\, s \in F : a \in s \wedge b \in s \,\}$,
equal to $\card{F}$ times the two-point correlation function.
\end{definition}

\begin{definition}[Union count]
For $a,b \in \alpha$, $\uc(a,b) := \#\{\, s \in F : a \in s \vee b \in s \,\}$.
\end{definition}

\begin{definition}[Union closure]
For finite $\alpha$, the \emph{union closure} of $F$ is
\[
\closure{F} := \Big\{\, s : \exists\, G \subseteq F,\ G \ne \varnothing,\
\textstyle\bigvee_{g \in G} g = s \,\Big\},
\]
the family of all sets obtainable as the supremum (union) of a nonempty
sub-collection of $F$.
\end{definition}

\section{Main results}

\begin{theorem}[Double-counting identity]\label{thm:double}
For any finite ground set $\alpha$ and family $F$,
\[
\sum_{a \in \alpha} \mc(a) \;=\; \sum_{s \in F} \card{s}.
\]
\end{theorem}

\begin{proof}[Proof sketch]
Expand $\mc(a) = \sum_{s \in F} \mathbf{1}[a \in s]$. The double sum
$\sum_{a}\sum_{s\in F}\mathbf{1}[a\in s]$ is symmetric in its indices; swapping
the order of summation (finite Fubini), the inner sum
$\sum_{a}\mathbf{1}[a\in s]$ equals $\card{s}$.
\end{proof}

\begin{theorem}[Majority from average]\label{thm:majority}
Let $\alpha$ be finite and nonempty and $F$ nonempty. If
$2\sum_{s \in F} \card{s} \ge \card{F}\cdot\card{\alpha}$, then there exists
$a \in \alpha$ with $2\,\mc(a) \ge \card{F}$.
\end{theorem}

\begin{proof}[Proof sketch]
Contrapositive. Assume $2\,\mc(a) < \card{F}$ for every $a$. Summing this strict
inequality over the nonempty index set $\alpha$ gives
$2\sum_{a}\mc(a) < \card{\alpha}\cdot\card{F}$. By Theorem~\ref{thm:double} the
left side is $2\sum_{s\in F}\card{s}$, contradicting the hypothesis.
\end{proof}

\begin{theorem}[Every upset is union-closed]\label{thm:bridge}
If $F$ is an upper-set family, then $F$ is union-closed.
\end{theorem}

\begin{proof}[Proof sketch]
For $s,t \in F$ we have $s \subseteq s \cup t$; applying the upper-set property
to $s \in F$ and this inclusion yields $s \cup t \in F$.
\end{proof}

\begin{theorem}[Inclusion--exclusion]\label{thm:ie}
For any $a,b \in \alpha$, as integers,
\[
\uc(a,b) \;=\; \mc(a) + \mc(b) - \jc(a,b).
\]
\end{theorem}

\begin{proof}[Proof sketch]
The event $\{a \in s \vee b \in s\}$ is the union, and
$\{a\in s \wedge b\in s\}$ the intersection, of $\{a\in s\}$ and $\{b\in s\}$. By
$\card{X\cup Y}+\card{X\cap Y}=\card{X}+\card{Y}$ applied to the filtered
subfamilies, $\uc(a,b)+\jc(a,b)=\mc(a)+\mc(b)$; rearrange over $\mathbb{Z}$.
\end{proof}

\begin{lemma}[Extensiveness]\label{lem:ext}
$F \subseteq \closure{F}$.
\end{lemma}

\begin{proof}[Proof sketch]
Each $s \in F$ equals the supremum of the nonempty singleton sub-collection
$\{s\}\subseteq F$, hence lies in $\closure{F}$.
\end{proof}

\begin{lemma}[Closure is union-closed]\label{lem:closed}
$\closure{F}$ is a union-closed family.
\end{lemma}

\begin{proof}[Proof sketch]
If $s = \bigvee_{g\in G_1} g$ and $t = \bigvee_{g\in G_2} g$ with nonempty
$G_1,G_2\subseteq F$, then $s\cup t = \bigvee_{g\in G_1\cup G_2} g$ with
$G_1\cup G_2\subseteq F$ nonempty, so $s\cup t\in\closure{F}$.
\end{proof}

\begin{theorem}[Monotonicity of total occupancy under closure]\label{thm:mono}
\[
\sum_{s \in F} \card{s} \;\le\; \sum_{s \in \closure{F}} \card{s}.
\]
\end{theorem}

\begin{proof}[Proof sketch]
By Lemma~\ref{lem:ext}, $F\subseteq\closure{F}$; since $\card{s}\ge 0$, summing
the nonnegative quantity over the larger index set dominates.
\end{proof}

\begin{theorem}[Nonnegative correlation on the full powerset]\label{thm:fkg}
Let $\alpha$ be finite. For any $a,b \in \alpha$, on $F = 2^\alpha$,
\[
\card{2^\alpha}\cdot \jc(a,b) \;\ge\; \mc(a)\cdot \mc(b).
\]
\end{theorem}

\begin{proof}[Proof sketch]
The counting lemma $\#\{\, t \subseteq \alpha : s \subseteq t \,\} =
2^{\card{\alpha} - \card{s}}$ follows from the bijection $t \mapsto t\setminus
s$. If $a=b$ the claim is $\mc(a)\le\card{2^\alpha}$, true since the filtered
subfamily is a subfamily. If $a\ne b$, the lemma gives
$\mc(a)=\mc(b)=2^{\card{\alpha}-1}$ and $\jc(a,b)=2^{\card{\alpha}-2}$, whence
both sides equal $2^{2\card{\alpha}-2}$ (equality).
\end{proof}

Rescaling Theorem~\ref{thm:fkg} reads $P(a\cap b)\ge P(a)P(b)$: coordinate
indicators are positively correlated, the base case of the
Fortuin--Kasteleyn--Ginibre inequality.

\section{Algorithms}

\textbf{Observable evaluation.} Compute $\mc,\jc,\uc$ by a linear scan over the
members of $F$ in $O(\card{F}\cdot\card{\alpha})$, then verify
Theorems~\ref{thm:double} and~\ref{thm:ie} arithmetically.

\textbf{Union-closure construction.} Maintain a worklist initialized to $F$;
repeatedly add pairwise unions until a fixed point is reached (terminating since
the subset universe is finite). The result is $\closure{F}$
(Lemmas~\ref{lem:ext}--\ref{lem:closed}); comparing total occupancy before and
after demonstrates Theorem~\ref{thm:mono}.

\textbf{Frankl-direction certificate.} Test
$2\sum_s\card{s}\ge\card{F}\cdot\card{\alpha}$; if it holds, return a witness $a$
with $2\,\mc(a)\ge\card{F}$ (Theorem~\ref{thm:majority}).

\section{Applications and discussion}

Theorem~\ref{thm:fkg} seeds discrete correlation inequalities;
Theorem~\ref{thm:bridge} identifies monotone events inside the union-closed
world. Theorem~\ref{thm:majority} settles the Frankl conclusion in the
dense-average regime, localizing the open difficulty to low-density families.
Theorems~\ref{thm:double} and~\ref{thm:ie} are exact sum rules for occupancy and
correlation, and Theorem~\ref{thm:mono} quantifies an irreversible,
mass-non-decreasing coarse-graining step.

\section{Future work}

Extend Theorem~\ref{thm:fkg} from the full powerset to general union-closed
families with product-like measures (a finite FKG inequality); replace the
averaged hypothesis of Theorem~\ref{thm:majority} by a structural one toward the
full Frankl conjecture, possibly via an information-theoretic refinement of
Theorem~\ref{thm:double}; and sharpen Theorem~\ref{thm:mono} to a strict
entropy-production estimate for the closure step.

\section{Conclusion}

We have assembled, with full formal backing, a compact theory presenting
union-closed families as positive-correlation systems: a conservation law, an
order-parameter principle, an order-theoretic bridge, the two-point
inclusion--exclusion law, a closure operator with occupancy monotonicity, and
the FKG base case.

